import {controller, target} from '@github/catalyst'

@controller
export class PaymentHistoryElement extends HTMLElement {
  @target noInvoiceFoundBanner: HTMLElement
  @target transactionIdNotFound: HTMLElement
  @target transactionIdTimeout: HTMLElement
  @target generalErrorBanner: HTMLElement
  @target timeoutBanner: HTMLElement

  connectedCallback() {
    this.hideBanners()
  }

  showNoInvoiceFoundBanner(event: Event) {
    const eventDetail = (event as CustomEvent).detail
    const transactionId = eventDetail.transactionId
    this.noInvoiceFoundBanner.style.display = ''
    this.transactionIdNotFound.textContent = transactionId
  }

  showGeneralErrorBanner(_event: Event) {
    this.generalErrorBanner.style.display = ''
  }

  showTimeoutBanner(event: Event) {
    const eventDetail = (event as CustomEvent).detail
    const transactionId = eventDetail.transactionId
    this.timeoutBanner.style.display = ''
    this.transactionIdTimeout.textContent = transactionId
  }

  hideBanners() {
    this.noInvoiceFoundBanner.style.display = 'none'
    this.generalErrorBanner.style.display = 'none'
    this.timeoutBanner.style.display = 'none'
  }
}
